      index += 1;
      break;
    }
    index += 1;
  }

  return {
    html: collected.join("\n"),
    next: index,
  };
}

function readParagraph(lines, start, context) {
  const paragraphLines = [];
  let index = start;

  while (index < lines.length && !paragraphStop(lines, index, context)) {
    paragraphLines.push(lines[index]);
    index += 1;
  }

  const content = paragraphLines.join("\n");
  return {
    html: `<p>${renderInline(content, context)}</p>`,
    next: index,
  };
}

export function renderBlocks(lines, context) {
  const parts = [];
  let index = 0;

  while (index < lines.length) {
    if (isBlank(lines[index])) {
      index += 1;
      continue;
    }

    const fenced = readFencedCode(lines, index, context);
    if (fenced) {
      parts.push(fenced.html);
      index = fenced.next;
      continue;
    }

    const markdownHtml = readMarkdownHtml(lines, index, context);
    if (markdownHtml) {
      parts.push(markdownHtml.html);
      index = markdownHtml.next;
      continue;
    }

    const indentedCode = readIndentedCode(lines, index);
    if (indentedCode) {
      parts.push(indentedCode.html);
      index = indentedCode.next;
      continue;
    }

    const heading = readHeading(lines, index, context);
    if (heading) {
      parts.push(heading.html);
      index = heading.next;
      continue;
    }

    if (isHorizontalRule(lines[index])) {
      parts.push("<hr />");
      index += 1;
      continue;
    }

    const blockquote = readBlockquote(lines, index, context);
    if (blockquote) {
      parts.push(blockquote.html);
      index = blockquote.next;
      continue;
    }

    const list = readList(lines, index, context);
    if (list) {
      parts.push(list.html);
      index = list.next;
      continue;
    }

    const table = readTable(lines, index, context);
    if (table) {
      parts.push(table.html);
      index = table.next;
      continue;
    }

    const definitionList = readDefinitionList(lines, index, context);
    if (definitionList) {
      parts.push(definitionList.html);
      index = definitionList.next;
      continue;
    }

    const rawHtml = readRawHtml(lines, index);
    if (rawHtml) {
      parts.push(rawHtml.html);
      index = rawHtml.next;
      continue;
    }

    const paragraph = readParagraph(lines, index, context);
    parts.push(paragraph.html);
    index = paragraph.next;
  }

  return parts.join("\n");
}

