import { renderBlocks } from "./blocks.mjs";
import { escapeAttribute, normalizeNewlines } from "./html.mjs";

function buildOptions(extensions) {
  const hasExtra = extensions.includes("extra");
  const hasTables = hasExtra || extensions.includes("tables");

  return {
    tables: hasTables,
    fencedCode: hasExtra,
    definitionLists: hasExtra,
    footnotes: hasExtra,
    abbreviations: hasExtra,
    markdownInHtml: hasExtra,
  };
}

function stripContinuationIndent(line) {
  if (line.startsWith("\t")) {
    return line.slice(1);
  }

  let count = 0;
  while (count < 4 && count < line.length && line[count] === " ") {
    count += 1;
  }
  return line.slice(count);
}

function parseAbbreviation(line) {
  const trimmed = line.trim();
  if (!trimmed.startsWith("*[")) {
    return null;
  }

  const close = trimmed.indexOf("]:");
  if (close === -1) {
    return null;
  }

  const key = trimmed.slice(2, close);
  const title = trimmed.slice(close + 2).trim();
  if (!key) {
    return null;
  }

  return { key, title };
}

function parseFootnoteStart(line) {
  const trimmed = line.trim();
  if (!trimmed.startsWith("[^")) {
    return null;
  }

  const close = trimmed.indexOf("]:");
  if (close === -1) {
    return null;
  }

  const id = trimmed.slice(2, close);
  const value = trimmed.slice(close + 2).trimStart();
  if (!id) {
    return null;
  }

  return { id, value };
}

function extractDefinitions(lines, options) {
  const contentLines = [];
  const abbreviations = {};
  const footnoteDefinitions = {};
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];

    if (options.abbreviations) {
      const abbreviation = parseAbbreviation(line);
      if (abbreviation) {
        abbreviations[abbreviation.key] = abbreviation.title;
        index += 1;
        continue;
      }
    }

    if (options.footnotes) {
      const footnote = parseFootnoteStart(line);
      if (footnote) {
        const collected = [footnote.value];
        index += 1;
        while (index < lines.length) {
          if (lines[index].trim().length === 0) {
            collected.push("");
            index += 1;
            continue;
          }

          if (lines[index].startsWith("    ") || lines[index].startsWith("\t")) {
            collected.push(stripContinuationIndent(lines[index]));
            index += 1;
            continue;
          }

          break;
        }
        footnoteDefinitions[footnote.id] = collected;
        continue;
      }
    }

    contentLines.push(line);
    index += 1;
  }

  return {
    contentLines,
    abbreviations,
    footnoteDefinitions,
  };
}

function appendBackref(html, id, number) {
  const safeId = escapeAttribute(id);
  const backref = `<a class="footnote-backref" href="#fnref:${safeId}" title="Jump back to footnote ${number} in the text">&#8617;</a>`;

  if (html.endsWith("</p>")) {
    return `${html.slice(0, html.length - 4)}&#160;${backref}</p>`;
  }

  if (html.length === 0) {
    return `<p>${backref}</p>`;
  }

  return `${html}\n<p>${backref}</p>`;
}

function renderFootnotes(context) {
  if (context.footnoteOrder.length === 0) {
    return "";
  }

  const items = [];
  let index = 0;
  while (index < context.footnoteOrder.length) {
    const id = context.footnoteOrder[index];
    const number = index + 1;
    const definitionLines = context.footnoteDefinitions[id] ?? [""];
    const html = renderBlocks(definitionLines, context);
    const content = appendBackref(html, id, number);
    items.push(`<li id="fn:${escapeAttribute(id)}">\n${content}\n</li>`);
    index += 1;
  }

  return [
    '<div class="footnote">',
    "<hr />",
    "<ol>",
    items.join("\n"),
    "</ol>",
    "</div>",
  ].join("\n");
}

export function renderMarkdown(source, extensions = []) {
  const options = buildOptions(extensions);
  const normalized = normalizeNewlines(source);
  const lines = normalized.length === 0 ? [] : normalized.split("\n");
  const definitions = extractDefinitions(lines, options);
  const abbreviationKeys = Object.keys(definitions.abbreviations).sort((left, right) => right.length - left.length);

  const context = {
    options,
    abbreviations: definitions.abbreviations,
    abbreviationKeys,
    footnoteDefinitions: definitions.footnoteDefinitions,
    footnoteReferences: {},
    footnoteOrder: [],
  };

  const body = renderBlocks(definitions.contentLines, context);
  const footnotes = renderFootnotes(context);

  if (body.length === 0) {
    return footnotes;
  }

  if (footnotes.length === 0) {
    return body;
  }

  return `${body}\n${footnotes}`;
}

