import { basename } from './text.mjs';

export function getProgramName(scriptPath) {
  const name = basename(scriptPath);
  return name.length === 0 ? 'test11.mjs' : name;
}

export function buildHelpText(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C

Markdown with extension configuration

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
`;
}

export function buildUsageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C\n`;
}

export function parseArguments(argv) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { kind: 'help' };
    }

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

    const option = matchOptionToken(token);
    if (option !== null) {
      if (option.hasAttachedValue) {
        values[option.name] = option.value;
        index += 1;
        continue;
      }

      if (index + 1 >= argv.length || isOptionLike(argv[index + 1])) {
        return {
          kind: 'error',
          message: `argument --${option.name}: expected one argument`,
        };
      }

      values[option.name] = argv[index + 1];
      index += 2;
      continue;
    }

    extras.push(token);
    index += 1;
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }
  if (values.b === undefined) {
    missing.push('--b');
  }
  if (values.c === undefined) {
    missing.push('--c');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

function matchOptionToken(token) {
  const names = ['a', 'b', 'c'];

  for (let i = 0; i < names.length; i += 1) {
    const name = names[i];
    const flag = `--${name}`;

    if (token === flag) {
      return {
        name,
        hasAttachedValue: false,
        value: '',
      };
    }

    if (token.startsWith(flag + '=')) {
      return {
        name,
        hasAttachedValue: true,
        value: token.slice(flag.length + 1),
      };
    }
  }

  return null;
}

function isOptionLike(token) {
  return token.length > 0 && token[0] === '-';
}

