import { escapeHtmlAttribute, escapeHtmlText } from './html.mjs';
import { renderInline } from './inline.mjs';
import {
  countLeadingSpaces,
  isAsciiLetter,
  isBlank,
  isDigitChar,
  splitPipeCells,
  trimLeftSpaces,
  trimRightSpaces,
  trimSpaces,
} from './text.mjs';

const BLOCK_TAGS = new Set([
  'address',
  'article',
  'aside',
  'blockquote',
  'body',
  'caption',
  'center',
  'col',
  'colgroup',
  'dd',
  'details',
  'dialog',
  'dir',
  'div',
  'dl',
  'dt',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'frame',
  'frameset',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'head',
  'header',
  'hr',
  'html',
  'iframe',
  'legend',
  'li',
  'main',
  'menu',
  'nav',
  'noframes',
  'ol',
  'p',
  'pre',
  'script',
  'section',
  'style',
  'summary',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'title',
  'tr',
  'ul',
]);

const VOID_BLOCK_TAGS = new Set(['hr', 'col']);

export function renderBlocks(lines, mode) {
  const parts = [];
  let index = 0;

  while (index < lines.length) {
    if (isBlank(lines[index])) {
      index += 1;
      continue;
    }

    if (mode === 'extra') {
      const fence = parseFenceBlock(lines, index);
      if (fence !== null) {
        parts.push(fence.html);
        index = fence.nextIndex;
        continue;
      }
    }

    const htmlBlock = parseHtmlBlock(lines, index);
    if (htmlBlock !== null) {
      parts.push(htmlBlock.html);
      index = htmlBlock.nextIndex;
      continue;
    }

    if (isHorizontalRule(lines[index])) {
      parts.push('<hr />');
      index += 1;
      continue;
    }

    if (mode === 'tables' || mode === 'extra') {
      const table = parseTableBlock(lines, index);
      if (table !== null) {
        parts.push(table.html);
        index = table.nextIndex;
        continue;
      }
    }

    const heading = parseHeading(lines[index]);
    if (heading !== null) {
      parts.push(heading);
      index += 1;
      continue;
    }

    const blockquote = parseBlockquote(lines, index, mode);
    if (blockquote !== null) {
      parts.push(blockquote.html);
      index = blockquote.nextIndex;
      continue;
    }

    const list = parseList(lines, index);
    if (list !== null) {
      parts.push(list.html);
      index = list.nextIndex;
      continue;
    }

    const paragraph = parseParagraph(lines, index, mode);
    parts.push(paragraph.html);
    index = paragraph.nextIndex;
  }

  return parts.join('\n');
}

function parseFenceBlock(lines, startIndex) {
  const open = parseFenceOpen(lines[startIndex]);
  if (open === null) {
    return null;
  }

  let endIndex = startIndex + 1;

  while (endIndex < lines.length) {
    if (isFenceClose(lines[endIndex], open.tickCount)) {
      const bodyLines = lines.slice(startIndex + 1, endIndex);
      let body = bodyLines.join('\n');
      if (bodyLines.length > 0) {
        body += '\n';
      }

      const language = trimSpaces(open.info);
      const classAttribute = language.length === 0
        ? ''
        : ` class="language-${escapeHtmlAttribute(language)}"`;

      return {
        html: `<pre><code${classAttribute}>${escapeHtmlText(body)}</code></pre>`,
        nextIndex: endIndex + 1,
      };
    }

    endIndex += 1;
  }

  return null;
}

function parseFenceOpen(line) {
  const spaces = countLeadingSpaces(line);
  if (spaces > 3) {
    return null;
  }

  let index = spaces;
  let tickCount = 0;

  while (index < line.length && line[index] === '`') {
    tickCount += 1;
    index += 1;
  }

  if (tickCount < 3) {
    return null;
  }

  return {
    tickCount,
    info: line.slice(index),
  };
}

function isFenceClose(line, tickCount) {
  const spaces = countLeadingSpaces(line);
  if (spaces > 3) {
    return false;
  }

  let index = spaces;
  let seen = 0;

  while (index < line.length && line[index] === '`') {
    seen += 1;
    index += 1;
  }

  if (seen < tickCount) {
    return false;
  }

  for (let i = index; i < line.length; i += 1) {
    const char = line[i];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return true;
}

function parseHtmlBlock(lines, startIndex) {
  const start = getHtmlBlockStart(lines[startIndex]);
  if (start === null) {
    return null;
  }

  const collected = [lines[startIndex]];

  if (VOID_BLOCK_TAGS.has(start.tagName) || lineContainsClosingTag(lines[startIndex], start.tagName)) {
    return {
      html: collected.join('\n'),
      nextIndex: startIndex + 1,
    };
  }

  let index = startIndex + 1;

  while (index < lines.length) {
    collected.push(lines[index]);
    if (lineContainsClosingTag(lines[index], start.tagName)) {
      return {
        html: collected.join('\n'),
        nextIndex: index + 1,
      };
    }
    index += 1;
  }

  return {
    html: collected.join('\n'),
    nextIndex: lines.length,
  };
}

function getHtmlBlockStart(line) {
  if (countLeadingSpaces(line) !== 0 || line.length < 3 || line[0] !== '<') {
    return null;
  }

  let index = 1;

  if (line[index] === '/') {
    index += 1;
  }

  if (index >= line.length || !isAsciiLetter(line[index])) {
    return null;
  }

  let tagName = '';

  while (index < line.length) {
    const char = line[index];
    if (!isAsciiLetter(char) && !isDigitChar(char)) {
      break;
    }
    tagName += char.toLowerCase();
    index += 1;
  }

  if (!BLOCK_TAGS.has(tagName)) {
    return null;
  }

  return { tagName };
}

function lineContainsClosingTag(line, tagName) {
  const lower = line.toLowerCase();
  return lower.indexOf(`</${tagName}`) !== -1;
}

function isHorizontalRule(line) {
  const trimmed = trimSpaces(line);
  if (trimmed.length < 3) {
    return false;
  }

  const marker = trimmed[0];
  if (marker !== '-' && marker !== '*' && marker !== '_') {
    return false;
  }

  let count = 0;

  for (let i = 0; i < trimmed.length; i += 1) {
    const char = trimmed[i];
    if (char === marker) {
      count += 1;
      continue;
    }
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return count >= 3;
}

function parseTableBlock(lines, startIndex) {
  if (startIndex + 1 >= lines.length) {
    return null;
  }

  const headerCells = parseTableRow(lines[startIndex]);
  if (headerCells === null || headerCells.length === 0) {
    return null;
  }

  const alignments = parseTableDivider(lines[startIndex + 1]);
  if (alignments === null || alignments.length !== headerCells.length) {
    return null;
  }

  const bodyRows = [];
  let index = startIndex + 2;

  while (index < lines.length) {
    if (isBlank(lines[index])) {
      break;
    }

    const row = parseTableRow(lines[index]);
    if (row === null) {
      break;
    }

    bodyRows.push(normalizeCellCount(row, headerCells.length));
    index += 1;
  }

  let html = '<table>\n<thead>\n<tr>';

  for (let i = 0; i < headerCells.length; i += 1) {
    html += `\n<th${alignmentAttribute(alignments[i])}>${renderInline(headerCells[i])}</th>`;
  }

  html += '\n</tr>\n</thead>';

  if (bodyRows.length > 0) {
    html += '\n<tbody>';

    for (let rowIndex = 0; rowIndex < bodyRows.length; rowIndex += 1) {
      html += '\n<tr>';
      const row = bodyRows[rowIndex];
      for (let cellIndex = 0; cellIndex < headerCells.length; cellIndex += 1) {
        html += `\n<td${alignmentAttribute(alignments[cellIndex])}>${renderInline(row[cellIndex])}</td>`;
      }
      html += '\n</tr>';
    }

    html += '\n</tbody>';
  }

  html += '\n</table>';

  return {
    html,
    nextIndex: index,
  };
}

function parseTableRow(line) {
  if (line.indexOf('|') === -1) {
    return null;
  }

  const cells = splitPipeCells(line);
  if (cells.length === 0) {
    return null;
  }

  return cells;
}

function parseTableDivider(line) {
  const cells = parseTableRow(line);
  if (cells === null) {
    return null;
  }

  const alignments = [];

  for (let i = 0; i < cells.length; i += 1) {
    const alignment = parseAlignment(cells[i]);
    if (alignment === null) {
      return null;
    }
    alignments.push(alignment);
  }

  return alignments;
}

function parseAlignment(cell) {
  const text = trimSpaces(cell);
  if (text.length === 0) {
    return null;
  }

  let start = 0;
  let end = text.length;
  let left = false;
  let right = false;

  if (text[start] === ':') {
    left = true;
    start += 1;
  }

  if (end > start && text[end - 1] === ':') {
    right = true;
    end -= 1;
  }

  if (end <= start) {
    return null;
  }

  let dashCount = 0;

  for (let i = start; i < end; i += 1) {
    if (text[i] !== '-') {
      return null;
    }
    dashCount += 1;
  }

  if (dashCount === 0) {
    return null;
  }

  if (left && right) {
    return 'center';
  }

  if (left) {
    return 'left';
  }

  if (right) {
    return 'right';
  }

