  let level = 0;

  while (level < line.length && line[level] === '#') {
    level += 1;
  }

  if (level < 1 || level > 6 || level >= line.length || line[level] !== ' ') {
    return null;
  }

  let content = trimSpaces(line.slice(level + 1));

  while (content.length > 0 && content[content.length - 1] === '#') {
