const ESCAPABLE_CHARS = '\\`*_{}[]()#+-.!<>';

export function renderInline(text) {
  return renderInlineRange(text, 0, text.length);
}

function renderInlineRange(text, start, end) {
  let out = '';
  let index = start;

  while (index < end) {
    const char = text[index];

    if (char === '\\') {
      if (index + 1 < end && isEscapable(text[index + 1])) {
        out += escapeHtmlText(text[index + 1]);
        index += 2;
      } else {
        out += '\\';
        index += 1;
      }
      continue;
    }

    if (char === '`') {
      const ticks = countRun(text, index, '`');
      const close = findCodeSpanClose(text, index + ticks, end, ticks);

      if (close !== -1) {
        let code = text.slice(index + ticks, close);

        if (code.length >= 2 && code[0] === ' ' && code[code.length - 1] === ' ') {
          let hasNonSpace = false;
          for (let i = 1; i < code.length - 1; i += 1) {
