              hasNonSpace = true;
              break;
            }
          }

          if (hasNonSpace) {
            code = code.slice(1, code.length - 1);
          }
        }

        out += `<code>${escapeHtmlText(code)}</code>`;
        index = close + ticks;
        continue;
      }
    }

    if (char === '[') {
      const link = parseLink(text, index, end);
      if (link !== null) {
        out += link.html;
        index = link.nextIndex;
        continue;
      }
    }

    if (char === '<') {
      const angle = parseAngleConstruct(text, index, end);
      if (angle !== null) {
        out += angle.html;
        index = angle.nextIndex;
        continue;
      }
    }

