      const strong = parseDelimited(text, index, end, char + char, 'strong');
      if (strong !== null) {
        out += strong.html;
        index = strong.nextIndex;
        continue;
      }
    }

    if (char === '*' || char === '_') {
      const emphasis = parseDelimited(text, index, end, char, 'em');
      if (emphasis !== null) {
        out += emphasis.html;
        index = emphasis.nextIndex;
        continue;
      }
    }

    out += escapeHtmlText(char);
    index += 1;
  }

  return out;
}

function isEscapable(char) {
  return ESCAPABLE_CHARS.indexOf(char) !== -1;
}

function countRun(text, index, char) {
  let count = 0;

  while (index + count < text.length && text[index + count] === char) {
    count += 1;
  }

  return count;
}

function findCodeSpanClose(text, start, end, ticks) {
  let index = start;

  while (index < end) {
    if (text[index] !== '`') {
      index += 1;
      continue;
    }

