  let depth = 0;

  for (let index = start; index < end; index += 1) {
    const char = text[index];

    if (char === '\\') {
      index += 1;
      continue;
    }

    if (char === '[') {
      depth += 1;
      continue;
    }

    if (char === ']') {
      if (depth === 0) {
        return index;
      }
      depth -= 1;
    }
  }

  return -1;
}

function findLinkDestinationEnd(text, start, end) {
  for (let index = start; index < end; index += 1) {
    const char = text[index];

    if (char === '\\') {
      index += 1;
      continue;
    }

    if (char === ')') {
      return index;
    }
  }

  return -1;
}

function parseAngleConstruct(text, index, end) {
  const close = findAngleClose(text, index + 1, end);
  if (close === -1) {
    return null;
  }

  const inner = text.slice(index + 1, close);

  if (isAutolink(inner)) {
    const href = escapeHtmlAttribute(inner);
    return {
      html: `<a href="${href}">${escapeHtmlText(inner)}</a>`,
      nextIndex: close + 1,
    };
  }

  if (looksLikeInlineHtml(inner)) {
    return {
      html: `<${inner}>`,
      nextIndex: close + 1,
    };
  }

  return null;
}

function findAngleClose(text, start, end) {
  for (let index = start; index < end; index += 1) {
    const char = text[index];

    if (char === '\n') {
      return -1;
    }

    if (char === '>') {
      return index;
    }
  }

  return -1;
}

function isAutolink(inner) {
  if (inner.length === 0 || containsWhitespace(inner)) {
    return false;
  }

  return inner.indexOf('://') !== -1;
}

function looksLikeInlineHtml(inner) {
  if (inner.length === 0) {
    return false;
  }

  let index = 0;

  if (inner[index] === '/') {
    index += 1;
  }

  if (index >= inner.length || !isAsciiLetter(inner[index])) {
    return false;
  }

  index += 1;

  while (index < inner.length) {
    const char = inner[index];
    if (!isAsciiLetter(char) && !isDigitChar(char) && char !== '-') {
      break;
    }
    index += 1;
  }

  return true;
}

function parseDelimited(text, index, end, delimiter, tagName) {
  const contentStart = index + delimiter.length;
  const close = findClosingDelimiter(text, contentStart, end, delimiter);

  if (close === -1 || close === contentStart) {
    return null;
  }

  return {
    html: `<${tagName}>${renderInlineRange(text, contentStart, close)}</${tagName}>`,
    nextIndex: close + delimiter.length,
  };
}

function findClosingDelimiter(text, start, end, delimiter) {
  for (let index = start; index <= end - delimiter.length; index += 1) {
    if (text[index] === '\\') {
      index += 1;
      continue;
    }

    if (!startsWithAt(text, delimiter, index)) {
      continue;
    }

    if (delimiter.length === 1) {
      const previous = index > 0 ? text[index - 1] : '';
      const next = index + 1 < text.length ? text[index + 1] : '';

      if (previous === delimiter || next === delimiter) {
        continue;
      }
    }

    return index;
  }

  return -1;
}

