import { basename } from 'node:path';
import { buildErrorText, buildHelpText } from './messages.mjs';

const OPTION_TO_KEY = {
  '--a': 'a',
  '--b': 'b',
  '--c': 'c',
};

const REQUIRED_OPTIONS = ['--a', '--b', '--c'];

export class CliExit extends Error {
  constructor(exitCode, streamName, output) {
    super(output);
    this.name = 'CliExit';
    this.exitCode = exitCode;
    this.streamName = streamName;
    this.output = output;
  }
}

function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test11.mjs';
  }

  return basename(scriptPath);
}

function getOptionName(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return token;
  }

  return token.slice(0, equalsIndex);
}

function getAttachedValue(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return null;
  }

  return token.slice(equalsIndex + 1);
}

function containsSpace(token) {
  for (let index = 0; index < token.length; index += 1) {
    if (token[index] === ' ') {
      return true;
    }
  }

  return false;
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isSimpleNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigitBeforeDot = false;

  while (index < token.length && isDigit(token[index])) {
    sawDigitBeforeDot = true;
    index += 1;
  }

  if (index === token.length) {
    return sawDigitBeforeDot;
  }

  if (token[index] !== '.') {
    return false;
  }

  index += 1;

  let sawDigitAfterDot = false;
  while (index < token.length && isDigit(token[index])) {
    sawDigitAfterDot = true;
    index += 1;
  }

  if (!sawDigitAfterDot) {
    return false;
  }

  return index === token.length;
}

function looksLikeOptionalToken(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  if (token === '-') {
    return false;
  }

  if (containsSpace(token)) {
    return false;
  }

  if (isSimpleNegativeNumber(token)) {
    return false;
  }

  return true;
}

function isHelpToken(token) {
  if (token === '--help') {
    return true;
  }

  return token.length > 1 && token[0] === '-' && token[1] === 'h' && (token.length === 2 || token[2] !== '=');
}

function isHelpWithAttachedValue(token) {
  return token.startsWith('--help=') || token.startsWith('-h=');
}

function buildMissingArgumentsMessage(values) {
  const missing = [];

  for (const optionName of REQUIRED_OPTIONS) {
    const key = OPTION_TO_KEY[optionName];
    if (values[key] === undefined) {
      missing.push(optionName);
    }
  }

  return missing;
}

export function parseCliArgs(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  let stopOptionParsing = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (stopOptionParsing) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      stopOptionParsing = true;
      continue;
    }

    if (isHelpWithAttachedValue(token)) {
      const attachedValue = getAttachedValue(token);
      throw new CliExit(
        2,
        'stderr',
        buildErrorText(programName, `argument -h/--help: ignored explicit argument '${attachedValue}'`),
      );
    }

    if (isHelpToken(token)) {
      throw new CliExit(0, 'stdout', buildHelpText(programName));
    }

    const optionName = getOptionName(token);
    const key = OPTION_TO_KEY[optionName];

    if (key !== undefined) {
      const attachedValue = getAttachedValue(token);

      if (attachedValue !== null) {
        values[key] = attachedValue;
        continue;
      }

      const nextToken = argv[index + 1];

      if (nextToken === undefined || looksLikeOptionalToken(nextToken)) {
        throw new CliExit(2, 'stderr', buildErrorText(programName, `argument ${optionName}: expected one argument`));
      }

      values[key] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = buildMissingArgumentsMessage(values);
  if (missing.length > 0) {
    throw new CliExit(
      2,
      'stderr',
      buildErrorText(programName, `the following arguments are required: ${missing.join(', ')}`),
    );
  }

  if (extras.length > 0) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `unrecognized arguments: ${extras.join(' ')}`));
  }

  return values;
}
